 const cols=[35,160,285,410,540,685],headers=["Mois","Bulletins","Cotisations","Renouvellements","Recouvrements","Total encaissé"];page.drawRectangle({x:30,y:height-105,width:780,height:28,color:navy});headers.forEach((h,j)=>page.drawText(h,{x:cols[j],y:height-95,size:8.5,font:bold,color:rgb(1,1,1)}));let y=height-132;monthRows.forEach((r,idx)=>{if(idx%2===1)page.drawRectangle({x:30,y:y-7,width:780,height:24,color:light});const vals=[r.label,String(r.bulletins),fmtEuro(r.nouveaux),fmtEuro(r.renouvellements),fmtEuro(r.recouvrements),fmtEuro(r.total)];vals.forEach((v,j)=>page.drawText(v,{x:cols[j],y,size:9,font:j===5?bold:font,color:navy}));y-=25});const total=reportTotals(monthRows);page.drawRectangle({x:30,y:y-8,width:780,height:26,color:light});["TOTAL",String(total.bulletins),fmtEuro(total.nouveaux),fmtEuro(total.renouvellements),fmtEuro(total.recouvrements),fmtEuro(total.total)].forEach((v,j)=>page.drawText(v,{x:cols[j],y,size:9.5,font:bold,color:navy}));
