 const logout=async()=>{await fetch("/api/auth/logout",{method:"POST"});setAuth({user:null,adminMode:null});setState(emptyState());setSync("Déconnecté")};
 const enterAdminMode=async delegateId=>{const r=await fetch("/api/auth/admin-mode",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({delegateId})});if(r.ok){await refreshSession();await loadState();await refreshDirectory()}};
 const exitAdminMode=async()=>{const r=await fetch("/api/auth/admin-mode",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({delegateId:null})});if(r.ok){await refreshSession();await loadState();await refreshDirectory()}};
