 const adminNav=[...adminCore,['reporting','Reporting',FileText],['team','Équipe',Users],['notes','Notes',StickyNote],['settings','Paramètres',Settings]];
 const go=k=>{setPage(k);setDetail(null);setMobile(false)};
 const openCompany=id=>{setDetail({type:"company",companyId:id});setMobile(false)};
