async function generateBulletin(company,membership,contact){
 const popup=window.open("","_blank");
 if(popup){popup.document.write(`<div style="font-family:Arial,sans-serif;padding:32px">Génération du bulletin…</div>`);popup.document.close()}
 try{
  const r=await fetch("/api/bulletin",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({company,membership,contact})});
  if(!r.ok){const j=await r.json().catch(()=>({}));throw new Error(j.error||"Impossible de générer le bulletin")}
  const blob=await r.blob();
  const url=URL.createObjectURL(blob);
  if(popup){popup.location.href=url}else{window.open(url,"_blank")}
  setTimeout(()=>URL.revokeObjectURL(url),60000);
  return true;
 }catch(e){if(popup)popup.close();alert(e.message||"Impossible de générer le bulletin");throw e}
}

