function NotesPage({state,persist}){const [target,setTarget]=useState("all"),[text,setText]=useState("");return <div className="grid two"><div className="card"><h2>Envoyer une note</h2><Field label="Destinataire"><select className="input" value={target} onChange={e=>setTarget(e.target.value)}><option value="all">Toute l’équipe</option>{state.members.map(m=><option key={m.id} value={m.id}>{m.name}</option>)}</select></Field><TextArea rows="7" value={text} onChange={setText}/><Button variant="primary" style={{marginTop:10}} onClick={()=>{if(text.trim()){persist({...state,notes:[{id:uid(),target,text,date:new Date().toISOString()},...state.notes]});setText("")}}}>Envoyer</Button></div><div className="card"><h2>Historique</h2>{state.notes.map(n=><div className="timelineitem simple" key={n.id}><strong>{n.text}</strong><span>{n.target==="all"?"Toute l’équipe":state.members.find(m=>m.id===n.target)?.name} · {new Date(n.date).toLocaleString("fr-FR")}</span></div>)}</div></div>}
function ReportingSummary({state,ownerId,start,end,admin}){const rows=reportRows(state,start,end,ownerId),total=reportTotals(rows);return <div className="card reportsummary"><div className="sectionhead"><div><h2>{admin?"Reporting de la période":"Mon reporting de la période"}</h2><p className="meta">Chiffres calculés automatiquement depuis les bulletins validés et les paiements reçus.</p></div></div><ReportTable rows={rows} total={total} compact/></div>}

