function ActionsPage({admin,ownerId,state,persist,onOpenCompany,onOpenMembership}){
 const [owner,setOwner]=useState(ownerId),[tab,setTab]=useState("tasks"),[period,setPeriod]=useState("all"),[search,setSearch]=useState(""),[selected,setSelected]=useState(null);
 const f=flatten(state,admin?owner:ownerId);const pendingMemberships=f.memberships.filter(m=>["Brouillon","À compléter","En cours","Bulletin généré","Bulletin envoyé","Bulletin signé reçu"].includes(m.status));
 let rows=f.actions.filter(a=>!a.done);if(period==="overdue")rows=rows.filter(a=>a.dueDate<today());if(period==="today")rows=rows.filter(a=>a.dueDate===today());if(period==="upcoming")rows=rows.filter(a=>a.dueDate>today());rows=rows.filter(a=>!search||[a.companyName,a.title,a.comment,a.type].join(" ").toLowerCase().includes(search.toLowerCase())).sort((a,b)=>(a.dueDate+a.dueTime).localeCompare(b.dueDate+b.dueTime));
 const done=a=>{const c=state.companies.find(x=>x.id===a.companyId);if(!c)return;persist({...state,companies:state.companies.map(x=>x.id===c.id?normalizeCompany({...x,actions:x.actions.map(y=>y.id===a.id?{...y,done:true}:y)}):x)});setSelected(null)};
 const membershipRows=pendingMemberships.filter(m=>!search||`${m.companyName} ${m.label}`.toLowerCase().includes(search.toLowerCase()));
 const groupRows=(items,getDate)=>Object.entries(items.reduce((acc,item)=>{const key=getDate(item)||"";(acc[key]||(acc[key]=[])).push(item);return acc},{})).sort(([a],[b])=>a.localeCompare(b));
 const taskGroups=groupRows(rows,a=>a.dueDate);
 const membershipGroups=groupRows(membershipRows,m=>m.paymentDueDate||m.startDate);
 return <section className="data-page app-page actions-page-v157"><PageHead title="Tâches" subtitle="Vos relances, appels et actions à traiter, dans une vue simple.">{admin&&<select className="input compactselect" value={owner} onChange={e=>setOwner(e.target.value)}><option value="all">Toute l’équipe</option>{state.members.map(m=><option key={m.id} value={m.id}>{m.name}</option>)}</select>}</PageHead><div className="action-tabs app-segmented"><button className={tab==="tasks"?"active":""} onClick={()=>setTab("tasks")}>À réaliser <b>{f.actions.filter(a=>!a.done).length}</b></button><button className={tab==="memberships"?"active":""} onClick={()=>setTab("memberships")}>Adhésions à valider <b>{pendingMemberships.length}</b></button></div><div className="filters app-filterbar task-filter-v157"><div className="searchbox"><Search size={17}/><Input placeholder="Rechercher" value={search} onChange={setSearch}/></div>{tab!=="memberships"&&<select className="input compactselect" value={period} onChange={e=>setPeriod(e.target.value)}><option value="today">Aujourd’hui</option><option value="overdue">En retard</option><option value="upcoming">À venir</option><option value="all">Toutes</option></select>}</div>{tab==="tasks"?<div className="task-day-list">{taskGroups.map(([date,items])=><section className="task-day-group" key={date}><div className="task-day-label"><strong>{fmtAgendaDate(date)}</strong><span>{items.length} {items.length>1?"actions":"action"}</span></div><div className="task-day-items">{items.map(a=>{const c=state.companies.find(x=>x.id===a.companyId),ct=c?.contacts?.find(x=>x.id===a.contactId);return <article className="task-agenda-card task-agenda-card-compact" key={a.id} onClick={()=>setSelected(a)}><div className="task-time"><strong>{a.dueTime||"—"}</strong></div><div className="task-copy"><div className="task-badges"><Pill>{a.type}</Pill>{a.dueDate<today()&&<span className="late-chip">En retard</span>}</div><h3>{a.title}</h3><p>{a.companyName}{ct?` · ${[ct.firstName,ct.lastName].filter(Boolean).join(" ")}`:""}</p>{a.comment&&<small>{a.comment}</small>}</div><ChevronRight/></article>})}</div></section>)}{!rows.length&&<Empty title="Rien à traiter" text="Tout est à jour pour cette vue."/>}</div>:<div className="task-day-list membership-validation-list">{membershipGroups.map(([date,items])=><section className="task-day-group" key={date}><div className="task-day-label"><strong>{fmtAgendaDate(date)}</strong><span>{items.length} {items.length>1?"adhésions":"adhésion"}</span></div><div className="task-day-items">{items.map(m=><article className="task-agenda-card task-agenda-card-compact membership-validation-card" key={m.id} onClick={()=>onOpenMembership(m.companyId,m.id)}><div className="task-time membership-type-mini"><span>Adhésion</span></div><div className="task-copy"><div className="task-badges"><Pill value={membershipStatusGroup(m.status)}>{membershipStatusGroup(m.status)}</Pill></div><h3>{m.companyName}</h3><p>{m.label}</p></div><ChevronRight/></article>)}</div></section>)}{!membershipRows.length&&<Empty title="Aucune adhésion à valider"/>}</div>}{selected&&<TaskDrawer action={selected} state={state} persist={persist} onClose={()=>setSelected(null)} onOpenCompany={onOpenCompany} onDone={done}/>}</section>
}
function TaskDrawer({action,state,persist,onClose,onOpenCompany,onDone}){
 const company=state.companies.find(c=>c.id===action.companyId);if(!company)return null;const contact=company.contacts.find(c=>c.id===action.contactId)||company.contacts.find(c=>c.primary)||company.contacts[0];const [edit,setEdit]=useState(false),[form,setForm]=useState({...action});const contactName=contact?[contact.firstName,contact.lastName].filter(Boolean).join(" "):"Aucun contact lié";
 const save=()=>{persist({...state,companies:state.companies.map(c=>c.id===company.id?normalizeCompany({...c,actions:c.actions.map(a=>a.id===action.id?{...a,...form}:a)}):c)});setEdit(false)};
 const remove=()=>{if(!confirm("Supprimer cette tâche ?"))return;persist({...state,companies:state.companies.map(c=>c.id===company.id?normalizeCompany({...c,actions:c.actions.filter(a=>a.id!==action.id)}):c)});onClose()};
 return <div className="modalback" onClick={onClose}><section className="task-modal-v159" onClick={e=>e.stopPropagation()}><div className="task-modal-head-v159"><div><h2>{action.title}</h2><p>{company.name}{contact?` · ${contactName}`:""}</p></div><button className="icon-close" onClick={onClose}><X/></button></div>{!edit?<><div className="task-overview-v159"><div className="task-info-v159"><div><strong>Échéance</strong><span>{fmtDate(action.dueDate)}{action.dueTime?` · ${action.dueTime}`:""}</span></div><div><strong>Commentaire</strong><span>{action.comment||"Aucun commentaire"}</span></div></div><div className="task-contact-v159"><div><strong>Contact référent</strong><span>{contactName}</span>{contact?.role&&<small>{contact.role}</small>}</div>{contact&&<div className="task-contact-actions-v159">{contact.phone&&<a href={`tel:${contact.phone}`}><Phone/>Appeler</a>}{contact.phone&&<a href={`https://wa.me/${contact.phone.replace(/[^0-9]/g,"").replace(/^0/,"33")}`} target="_blank" rel="noreferrer"><MessageCircle/>WhatsApp</a>}{contact.email&&<a href={`mailto:${contact.email}`}><Mail/>Message</a>}</div>}<div className="task-contact-coords-v159">{contact?.phone&&<span>{contact.phone}</span>}{contact?.email&&<span>{contact.email}</span>}</div></div></div><div className="task-modal-footer-v159"><button className="task-delete-v159" onClick={remove}><Trash2/>Supprimer</button><div><Button onClick={()=>setEdit(true)}><Edit3/>Modifier</Button><Button onClick={()=>{onClose();onOpenCompany(company.id)}}><Building2/>Voir la fiche</Button><Button variant="primary" onClick={()=>onDone(action)}><CheckCircle2/>Marquer comme fait</Button></div></div></>:<><div className="drawer-form task-edit-form-v159"><Field label="Type"><Select value={form.type} onChange={v=>setForm({...form,type:v})} options={ACTION_TYPES}/></Field><Field label="Objet"><Input value={form.title} onChange={v=>setForm({...form,title:v})}/></Field><div className="formgrid"><Field label="Date"><Input type="date" value={form.dueDate} onChange={v=>setForm({...form,dueDate:v})}/></Field><Field label="Heure"><Input type="time" value={form.dueTime} onChange={v=>setForm({...form,dueTime:v})}/></Field></div><Field label="Contact"><select className="input" value={form.contactId||""} onChange={e=>setForm({...form,contactId:e.target.value})}><option value="">Aucun contact</option>{company.contacts.map(c=><option key={c.id} value={c.id}>{[c.firstName,c.lastName].filter(Boolean).join(" ")}</option>)}</select></Field><Field label="Commentaire"><TextArea rows="4" value={form.comment||""} onChange={v=>setForm({...form,comment:v})}/></Field></div><div className="modal-footer task-edit-footer-v160"><Button variant="primary" onClick={save}><Save/>Enregistrer</Button></div></>}</section></div>
}
function ContactDrawer({row,state,persist,onClose,onOpenCompany}){const [edit,setEdit]=useState(false);const company=state.companies.find(c=>c.id===row.companyId);if(!company)return null;const contact=company.contacts.find(c=>c.id===row.id)||row;const name=[contact.firstName,contact.lastName].filter(Boolean).join(" ");const save=updated=>{const contacts=company.contacts.map(c=>c.id===updated.id?updated:c);persist({...state,companies:state.companies.map(c=>c.id===company.id?normalizeCompany({...c,contacts}):c)});setEdit(false)};const whatsapp=contact.phone?`https://wa.me/${contact.phone.replace(/[^0-9]/g,"").replace(/^0/,"33")}`:"";const active=company.memberships.find(m=>m.status==="Active"&&(!m.endDate||m.endDate>=today()));const due=company.memberships.reduce((sum,m)=>sum+Math.max(0,Number(m.amountExpected||0)-sumReceived(m)),0);const logContactActivity=(type,title)=>persist({...state,companies:state.companies.map(c=>c.id===company.id?normalizeCompany({...c,activitiesLog:[{id:uid(),type,date:today(),title,comment:`${name||"Contact"} · ${contact.phone||contact.email||""}`},...(c.activitiesLog||[])]}):c)});return <>{!edit&&<div className="modalback" onClick={onClose}><section className="contact-preview-modal-v159 contact-directory-modal-v159" onClick={e=>e.stopPropagation()}><button className="icon-close" onClick={onClose}><X/></button><div className="contact-preview-heading-v159"><span className="contacticon large"><UserRound/></span><div><h2>{name||"Contact sans nom"}</h2><p>{contact.role||"Fonction non renseignée"} · {company.name}</p></div></div><div className="contact-preview-actions-v159">{contact.phone&&<a className="btn primary" href={`tel:${contact.phone}`} onClick={()=>logContactActivity("Appel","Appel lancé")}><Phone/>Appeler</a>}{whatsapp&&<a className="btn secondary" href={whatsapp} target="_blank" rel="noreferrer" onClick={()=>logContactActivity("Note","WhatsApp ouvert")}><MessageCircle/>WhatsApp</a>}{contact.email&&<a className="btn secondary" href={`mailto:${contact.email}`} onClick={()=>logContactActivity("Email","Email lancé")}><Mail/>Message</a>}</div><div className="contact-preview-details-v159"><div><span>Téléphone</span><strong>{contact.phone||"—"}</strong></div><div><span>Email</span><strong>{contact.email||"—"}</strong></div></div><div className="contact-company-preview-v159"><div><span>Aperçu entreprise</span><strong>{company.name}</strong><small>{effectiveStage(company)} · {active?.label||"Aucune adhésion active"} · Reste {fmtEuro(due)}</small></div><Button variant="primary" onClick={()=>{onClose();onOpenCompany(company.id)}}><Building2/>Voir la fiche entreprise</Button></div><div className="modal-footer"><Button onClick={()=>setEdit(true)}><Edit3/>Modifier le contact</Button></div></section></div>}{edit&&<ContactForm initial={contact} onClose={()=>setEdit(false)} onSave={save}/>}</>}
function ContactsPage({admin,ownerId,state,persist,onOpenCompany}){
 if(!admin)return <DelegateContactsPage ownerId={ownerId} state={state} persist={persist} onOpenCompany={onOpenCompany}/>;const [owner,setOwner]=useState(ownerId),[search,setSearch]=useState(""),[selected,setSelected]=useState(null);const rows=flatten(state,admin?owner:ownerId).contacts.filter(c=>!search||[c.firstName,c.lastName,c.role,c.phone,c.email,c.companyName].join(" ").toLowerCase().includes(search.toLowerCase())).sort((a,b)=>(a.lastName||"").localeCompare(b.lastName||""));return <section className="data-page"><PageHead title="Contacts">{admin&&<select className="input compactselect" value={owner} onChange={e=>setOwner(e.target.value)}><option value="all">Toute l’équipe</option>{state.members.map(m=><option key={m.id} value={m.id}>{m.name}</option>)}</select>}</PageHead><div className="filters"><div className="searchbox"><Search size={17}/><Input placeholder="Nom, entreprise, téléphone, email…" value={search} onChange={setSearch}/></div></div><div className="tablewrap"><table className="table"><thead><tr><th>Contact</th><th>Fonction</th><th>Entreprise</th><th>Téléphone</th><th>Email</th><th>Délégué</th></tr></thead><tbody>{rows.map(r=><tr className="clickrow" key={`${r.companyId}-${r.id}`} onClick={()=>setSelected(r)}><td><strong>{[r.firstName,r.lastName].filter(Boolean).join(" ")}</strong>{r.primary&&<small>Contact principal</small>}</td><td>{r.role||"—"}</td><td>{r.companyName}</td><td>{r.phone||"—"}</td><td>{r.email||"—"}</td><td>{state.members.find(m=>m.id===r.ownerId)?.name||"—"}</td></tr>)}</tbody></table>{!rows.length&&<Empty title="Aucun contact"/>}</div>{selected&&<ContactDrawer row={selected} state={state} persist={persist} onClose={()=>setSelected(null)} onOpenCompany={onOpenCompany}/>}</section>}
function DelegateContactsPage({ownerId,state,persist,onOpenCompany}){
 const [search,setSearch]=useState(""),[selected,setSelected]=useState(null);
 const rows=flatten(state,ownerId).contacts.filter(c=>!search||[c.firstName,c.lastName,c.role,c.phone,c.email,c.companyName].join(" ").toLowerCase().includes(search.toLowerCase())).sort((a,b)=>(a.lastName||"").localeCompare(b.lastName||""));
 return <section className="data-page v15-data-page"><div className="v15-page-title"><div><p className="v15-kicker">Annuaire</p><h1>Contacts</h1><p>Retrouvez et joignez rapidement les contacts de votre portefeuille.</p></div></div><div className="v15-filterbar"><div className="v15-search"><Search/><Input placeholder="Rechercher un contact, une entreprise, un téléphone…" value={search} onChange={setSearch}/></div><span className="v15-result-count">{rows.length} contact{rows.length>1?'s':''}</span></div><div className="v15-list-shell contact-list-shell-v161"><div className="v15-list-head contact-list-head-v161"><span>Contact</span><span>Entreprise</span><span>Coordonnées</span><span>Fonction</span><span></span></div>{rows.map(r=><div key={`${r.companyId}-${r.id}`} className="v15-list-row contact-list-row-v161" role="button" tabIndex={0} onClick={()=>setSelected(r)} onKeyDown={e=>{if(e.key==='Enter'||e.key===' ')setSelected(r)}}><span className="v15-list-company"><i>{((r.firstName||'').slice(0,1)+(r.lastName||'').slice(0,1)).toUpperCase()||'C'}</i><span><strong>{[r.firstName,r.lastName].filter(Boolean).join(' ')||'Contact sans nom'}</strong><small>{r.primary?'Contact principal':'Contact'}</small></span></span><span><strong>{r.companyName}</strong></span><span><strong>{r.phone||'—'}</strong><small>{r.email||'Email à compléter'}</small></span><span><strong>{r.role||'—'}</strong></span><span className="v15-next-action"><ChevronRight/></span></div>)}{!rows.length&&<Empty title="Aucun contact" text="Aucun résultat ne correspond à votre recherche."/>}</div>{selected&&<ContactDrawer row={selected} state={state} persist={persist} onClose={()=>setSelected(null)} onOpenCompany={onOpenCompany}/>}</section>
}

function SettingsPage({state,persist,admin,member}){const [org,setOrg]=useState(state.settings?.organization||"GHR Région Sud"),[saved,setSaved]=useState(false),[pwd,setPwd]=useState({password:"",confirm:""}),[pwdState,setPwdState]=useState({busy:false,message:"",error:""});const save=()=>{persist({...state,settings:{...(state.settings||{}),organization:org}});setSaved(true);setTimeout(()=>setSaved(false),1500)};const changePassword=async()=>{setPwdState({busy:false,message:"",error:""});if(pwd.password.length<8)return setPwdState({busy:false,message:"",error:"Le mot de passe doit contenir au moins 8 caractères."});if(pwd.password!==pwd.confirm)return setPwdState({busy:false,message:"",error:"Les deux mots de passe ne correspondent pas."});setPwdState({busy:true,message:"",error:""});const r=await fetch('/api/auth/change-password',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({password:pwd.password})});const j=await r.json().catch(()=>({}));if(!r.ok)return setPwdState({busy:false,message:"",error:j.error||"Modification impossible"});setPwd({password:"",confirm:""});setPwdState({busy:false,message:"Mot de passe modifié.",error:""})};return <section className="settings-page-v154"><PageHead title="Paramètres" subtitle={admin?"Réglages généraux de l’application.":"Mon compte."}/>{admin?<div className="settings-layout-v154"><nav className="settings-subnav"><button className="active">Organisation</button><button disabled>Sécurité</button></nav><div className="card settingscard"><h2>Organisation</h2><p className="meta">Informations utilisées dans l’interface et les documents générés.</p><Field label="Nom de l’organisation"><Input value={org} onChange={setOrg}/></Field><div className="settings-actions"><Button variant="primary" onClick={save}><Save/>Enregistrer</Button>{saved&&<span className="settings-saved">Enregistré</span>}</div></div></div>:<div className="settings-layout-v157"><div className="settings-stack-v155"><div className="card settingscard"><h2>Mon compte</h2><div className="summaryline"><span>Nom</span><strong>{member?.name||"—"}</strong></div><div className="summaryline"><span>Email</span><strong>{member?.email||"—"}</strong></div><div className="summaryline"><span>Profil</span><strong>Délégué</strong></div></div><div className="card settingscard"><h2>Sécurité</h2><p className="meta">Choisissez un nouveau mot de passe pour votre compte.</p><Field label="Nouveau mot de passe"><Input type="password" value={pwd.password} onChange={v=>setPwd({...pwd,password:v})}/></Field><Field label="Confirmer le mot de passe"><Input type="password" value={pwd.confirm} onChange={v=>setPwd({...pwd,confirm:v})}/></Field>{pwdState.error&&<p className="error">{pwdState.error}</p>}{pwdState.message&&<p className="auth-success">{pwdState.message}</p>}<Button variant="primary" disabled={pwdState.busy} onClick={changePassword}><Save/>{pwdState.busy?"Modification…":"Modifier le mot de passe"}</Button></div></div></div>}</section>}